// ============================================================================
// Public main-website translations (Home body, Schemes, Scheme detail, Ledger,
// About, 404, Forgot-password, the floating Assistant + shared SchemeCard) for
// the 14 major languages of India. Kept separate from the chrome/home-hero set
// in translations.ts and the portal-body set in translations.portal.ts; all
// three are merged into `dicts` in translations.ts. `en` is the master/fallback
// — any key missing from a language falls back to English, so languages can be
// filled in incrementally without leaking raw keys.
// Machine-assisted translations; native review recommended before production.
// ============================================================================
