  "home.spot.4.t": "निजी जाँच हेतु सरकारी संदर्भ रजिस्ट्री ऑन-चेन एंकर की गई",
  "sch.title": "कोई कल्याण योजना खोजें",
  "sch.sub": "क्षेत्रवार सक्रिय योजनाएँ देखें। पात्रता निजी रूप से जाँचने और आवेदन करने हेतु कोई एक चुनें — लाभ डिजिटल रुपया के रूप में आते हैं, जो केवल अनुमोदित विक्रेताओं पर खर्च योग्य हैं।",
