  "sch.upSub": "और नागरिक-से-विक्रेता कार्यक्रम ऑन-चेन जुड़ने की तैयारी में हैं — लाभ केवल उनके अनुमोदित विक्रेताओं पर ही खर्च हो सकेंगे, बिल्कुल चालू योजनाओं की तरह।",
  "sch.upBadge": "जल्द आ रही है",
  "sch.up.vishwakarma": "कारीगरों और शिल्पकारों के लिए e-RUPI औज़ार वाउचर, अधिकृत औज़ार विक्रेताओं पर भुनाए जा सकते हैं।",
  "sch.up.kusum": "किसानों के लिए सब्सिडी वाले सौर सिंचाई पंप, अनुमोदित विक्रेताओं के माध्यम से स्थापित।",
  "sch.up.suryaghar": "परिवारों के लिए छत-सौर सब्सिडी, पंजीकृत सोलर इंस्टॉलरों के माध्यम से।",
  "sch.up.pmjay": "सूचीबद्ध अस्पतालों में प्रति परिवार प्रति वर्ष ₹5 लाख तक का कैशलेस इलाज।",
  "sch.up.pds": "राशन-कार्ड धारकों के लिए लाइसेंस-प्राप्त उचित मूल्य दुकानों पर सब्सिडी वाला अनाज।",
  "sch.up.ujjwala": "पात्र परिवारों के लिए अधिकृत गैस वितरकों के माध्यम से सब्सिडी वाले LPG सिलेंडर।",
  "sd.allSchemes": "← सभी योजनाएँ",
  "sd.loadFail": "यह योजना लोड नहीं हो सकी: {err}",
  "sd.about": "इस योजना के बारे में",
  "sd.defaultDesc": "यह कल्याण योजना पात्र लाभार्थियों के ई-रुपया वॉलेट में निर्धारित किस्तों में सीधे लाभ वितरित करती है। पात्रता को शून्य-ज्ञान प्रमाण का उपयोग कर सरकारी रजिस्ट्री के विरुद्ध निजी रूप से सत्यापित किया जाता है, और प्रत्येक वितरण सार्वजनिक बही-खाता पर दर्ज होता है।",
  "sd.spendableAt": "लाभ खर्च योग्य यहाँ",
  "sd.howTitle": "यह कैसे काम करता है",
  "sd.step1.t": "पात्रता निजी रूप से जाँचें",
  "sd.step1.d": "आपके विवरण सरकारी रजिस्ट्री से मिलाए जाते हैं और शून्य-ज्ञान प्रमाण से सिद्ध किए जाते हैं — कोई संवेदनशील डेटा आपके उपकरण से असुरक्षित रूप से बाहर नहीं जाता।",
  "sd.step2.t": "ऑन-चेन नामांकन करें",
  "sd.step2.d": "प्रमाण सत्यापित होते ही, रिलेयर के माध्यम से आप सार्वजनिक बही-खाता पर योजना में नामांकित हो जाते हैं — कोई निजी कुंजी प्रबंधित करने की आवश्यकता नहीं।",
  "sd.step3.t": "डिजिटल रुपया प्राप्त करें",
  "sd.step3.d": "प्रत्येक किस्त निर्धारित समय पर सीधे आपके ई-रुपया वॉलेट में वितरित की जाती है।",
  "sd.step4.t": "अनुमोदित विक्रेताओं पर खर्च करें",
  "sd.step4.d": "अपने वॉलेट से सीधे अनुमोदित विक्रेताओं को भुगतान करें; प्रत्येक रुपया आरंभ से अंत तक सत्यापन-योग्य रहता है।",
