  "led.flowSub": "प्रत्येक लाभ उसी सत्यापन-योग्य मार्ग से होकर गुजरता है।",
  "led.flow1.t": "RBI स्वीकृति",
  "led.flow1.d": "रिज़र्व बैंक योजना निधि को डिजिटल रुपया के रूप में ऑन-चेन कोष में जारी करता है।",
