  "led.flow4.d": "विक्रेता ई-रुपया को वापस नकद में भुनाते हैं — RBI-अनुमोदित और पूर्णतः दर्ज।",
  "led.portalNote": "साइन-इन किए नागरिक और अधिकारी अपने पोर्टल के भीतर अपनी गतिविधि का लेन-देन-स्तरीय विवरण देखते हैं।",
  "abt.title": "कल्याण जिसे आप सत्यापित कर सकें, निजता जिस पर आप भरोसा कर सकें",
  "abt.sub": "BharatChain सरकारी लाभों को सार्वजनिक बही-खाता पर डिजिटल रुपया के रूप में प्रदान करता है — शून्य-ज्ञान प्रमाण के साथ प्रत्येक लाभार्थी के व्यक्तिगत डेटा को निजी रखते हुए रिसाव को समाप्त करता है।",
  "abt.browse": "योजनाएँ देखें",
  "abt.seeLedger": "बही-खाता देखें",
  "abt.principles": "चार सिद्धांत",
  "abt.pillar1.t": "डिज़ाइन से ही निजी",
  "abt.pillar1.d": "पात्रता को सरकारी रजिस्ट्री के विरुद्ध शून्य-ज्ञान प्रमाण से सिद्ध किया जाता है। प्रणाली केवल यह जानती है कि आप योग्य हैं — कभी आपका अंतर्निहित व्यक्तिगत डेटा नहीं।",
  "abt.pillar2.t": "सभी द्वारा सत्यापन-योग्य",
  "abt.pillar2.d": "स्वीकृतियाँ, वितरण और व्यय सार्वजनिक बही-खाता पर दर्ज होते हैं। कोई भी सत्यापित कर सकता है कि धन सही लोगों तक पहुँचा — बिना किसी पहचान उजागर किए।",
  "abt.pillar3.t": "न कुंजियाँ, न बाधा",
  "abt.pillar3.d": "एक सर्वर-साइड रिलेयर आपके लिए ऑन-चेन क्रियाओं पर हस्ताक्षर करता है। नागरिक एक फ़ोन नंबर से पंजीकरण करते हैं — खोने के लिए कोई वॉलेट या सीड फ़्रेज़ नहीं।",
  "abt.pillar4.t": "खर्च करें, मोड़ें नहीं",
  "abt.pillar4.d": "लाभ डिजिटल रुपया हैं जिन्हें केवल अनुमोदित, श्रेणी-मिलान वाले विक्रेताओं पर ही खर्च किया जा सकता है — नकद हस्तांतरण को त्रस्त करने वाले रिसाव को समाप्त करते हुए।",
  "abt.lifecycle": "स्वीकृति से व्यय तक",
  "abt.lifecycleSub": "BharatChain पर किसी लाभ का संपूर्ण जीवनचक्र।",
  "abt.step1.t": "सरकारी संदर्भ रजिस्ट्री",
  "abt.step1.d": "लाभार्थी और व्यवसाय पात्रता डेटा को मर्कल प्रतिबद्धता के रूप में ऑन-चेन एंकर किया जाता है — प्रमाणों के लिए सत्य का निजी स्रोत।",
  "abt.step2.t": "शून्य-ज्ञान पात्रता",
  "abt.step2.d": "एक नागरिक (या विक्रेता) यह प्रमाण उत्पन्न करता है कि वह किसी योजना के मानदंड को पूरा करता है — आय, श्रेणी, स्वामित्व — मूल्यों को उजागर किए बिना।",
  "abt.step3.t": "रिलेयर नामांकन",
  "abt.step3.d": "सत्यापित प्रमाण को ऑन-चेन रिले किया जाता है और लाभार्थी को उस विशिष्ट योजना के बही-खाता में नामांकित किया जाता है।",
  "abt.step4.t": "निर्धारित वितरण",
  "abt.step4.d": "प्रत्येक किस्त को ई-रुपया के रूप में जारी कर नामांकित वॉलेट में वितरित किया जाता है, देर से नामांकित होने वालों की भरपाई करते हुए और कुल राशि की सीमा तय करते हुए।",
  "abt.step5.t": "अनुमोदित विक्रेताओं पर खर्च करें",
  "abt.step5.d": "नागरिक सीधे विक्रेताओं को भुगतान करते हैं; भुगतान श्रेणी-सीमित होते हैं ताकि धनराशि को मोड़ा न जा सके।",
  "abt.step6.t": "विक्रेता मोचन",
  "abt.step6.d": "विक्रेता संचित ई-रुपया को RBI अनुमोदन के साथ नकद में भुनाते हैं — प्रत्येक चरण सार्वजनिक बही-खाता पर।",
  "abt.participants": "प्रत्येक प्रतिभागी के लिए निर्मित",
  "abt.role1.t": "नागरिक",
  "abt.role1.d": "योजनाओं हेतु आवेदन करें, पात्रता निजी रूप से सिद्ध करें, ई-रुपया प्राप्त करें और अनुमोदित विक्रेताओं पर खर्च करें।",
  "abt.role2.t": "विक्रेता",
  "abt.role2.d": "उन योजनाओं में ZK-नामांकित हों जिन्हें आपकी श्रेणी सेवा देती है, ई-रुपया स्वीकार करें, और नकद में भुनाएँ।",
  "abt.role3.t": "प्रशासक",
  "abt.role3.d": "वितरण दौर चलाएँ, विसंगतियों की निगरानी करें और अनुमोदित विक्रेता रजिस्ट्री का प्रबंधन करें।",
  "abt.role4.t": "रिज़र्व बैंक",
  "abt.role4.d": "योजना कोषों को स्वीकृत करें और विक्रेता मोचन को वापस नकद में अनुमोदित करें।",
  "abt.getStarted": "आरंभ करें →",
