  "abt.sub": "BharatChain सरकारी लाभ सार्वजनिक खातेवहीवर डिजिटल रुपया म्हणून पोहोचवते — शून्य-ज्ञान पुराव्यांसह प्रत्येक लाभार्थीचा वैयक्तिक डेटा खाजगी ठेवत गळती दूर करते.",
  "abt.browse": "योजना पहा",
