  "abt.pillar1.t": "रचनेनुसार खाजगी",
  "abt.pillar1.d": "पात्रता सरकारी रजिस्ट्रीच्या विरुद्ध शून्य-ज्ञान पुराव्याने सिद्ध केली जाते. प्रणालीला कळते की तुम्ही पात्र आहात — कधीही तुमचा अंतर्निहित वैयक्तिक डेटा नाही.",
