  "abt.pillar2.d": "मंजुऱ्या, वितरणे आणि खर्च सार्वजनिक खातेवहीवर नोंदवले जातात. कोणीही पडताळू शकतो की पैसे योग्य लोकांपर्यंत पोहोचले — कोणतीही ओळख उघड न करता.",
  "abt.pillar3.t": "की नाही, अडथळा नाही",
  "abt.pillar3.d": "सर्व्हर-साइड रिलेअर तुमच्यासाठी ऑन-चेन क्रिया स्वाक्षरित करतो. नागरिक फोन क्रमांकाने नोंदणी करतात — हरवण्यासारखे कोणतेही वॉलेट किंवा सीड फ्रेज नाही.",
  "abt.pillar4.t": "खर्च करा, वळवू नका",
