  "sch.sub": "రంగాల వారీగా క్రియాశీల పథకాలను చూడండి. అర్హతను గోప్యంగా తనిఖీ చేసి దరఖాస్తు చేయడానికి ఒకదాన్ని ఎంచుకోండి — ప్రయోజనాలు డిజిటల్ రూపాయిగా వస్తాయి, ఆమోదిత విక్రేతల వద్ద మాత్రమే ఖర్చు చేయదగినవి.",
