  "sd.about": "ఈ పథకం గురించి",
  "sd.defaultDesc": "ఈ సంక్షేమ పథకం అర్హులైన లబ్ధిదారుల ఇ-రూపాయి వాలెట్‌లకు షెడ్యూల్ చేయబడిన వాయిదాలలో నేరుగా ప్రయోజనాలను పంపిణీ చేస్తుంది. అర్హత జీరో-నాలెడ్జ్ ప్రూఫ్‌ను ఉపయోగించి ప్రభుత్వ రిజిస్ట్రీకి వ్యతిరేకంగా గోప్యంగా ధృవీకరించబడుతుంది, మరియు ప్రతి పంపిణీ పబ్లిక్ లెడ్జర్‌పై నమోదు చేయబడుతుంది.",
  "sd.spendableAt": "ప్రయోజనం ఖర్చు చేయదగిన చోటు",
  "sd.howTitle": "ఇది ఎలా పనిచేస్తుంది",
