  "sd.step1.d": "మీ వివరాలు ప్రభుత్వ రిజిస్ట్రీతో సరిపోల్చబడి జీరో-నాలెడ్జ్ ప్రూఫ్‌తో నిరూపించబడతాయి — ఏ సున్నితమైన డేటా మీ పరికరం నుండి అసురక్షితంగా బయటకు వెళ్లదు.",
