  "led.portalNote": "సైన్ ఇన్ చేసిన పౌరులు మరియు అధికారులు తమ పోర్టల్‌లో తమ స్వంత కార్యకలాపానికి లావాదేవీ-స్థాయి వివరాలను చూస్తారు.",
  "abt.title": "మీరు ధృవీకరించగల సంక్షేమం, మీరు విశ్వసించగల గోప్యత",
  "abt.sub": "BharatChain ప్రభుత్వ ప్రయోజనాలను పబ్లిక్ లెడ్జర్‌పై డిజిటల్ రూపాయిగా అందజేస్తుంది — జీరో-నాలెడ్జ్ ప్రూఫ్‌లతో ప్రతి లబ్ధిదారుని వ్యక్తిగత డేటాను గోప్యంగా ఉంచుతూ లీకేజీని తొలగిస్తుంది.",
  "abt.browse": "పథకాలను చూడండి",
  "abt.seeLedger": "లెడ్జర్‌ను చూడండి",
  "abt.principles": "నాలుగు సూత్రాలు",
  "abt.pillar1.t": "రూపకల్పన ద్వారా గోప్యం",
  "abt.pillar1.d": "అర్హత ప్రభుత్వ రిజిస్ట్రీకి వ్యతిరేకంగా జీరో-నాలెడ్జ్ ప్రూఫ్‌తో నిరూపించబడుతుంది. మీరు అర్హులని వ్యవస్థ తెలుసుకుంటుంది — మీ అంతర్లీన వ్యక్తిగత డేటాను ఎప్పుడూ కాదు.",
  "abt.pillar2.t": "ప్రతి ఒక్కరూ ఆడిట్ చేయదగినది",
  "abt.pillar2.d": "మంజూరులు, పంపిణీలు మరియు ఖర్చులు పబ్లిక్ లెడ్జర్‌పై నమోదు చేయబడతాయి. డబ్బు సరైన వ్యక్తులకు చేరిందని ఎవరైనా ధృవీకరించవచ్చు — ఏ గుర్తింపులు బహిర్గతం కాకుండా.",
  "abt.pillar3.t": "కీలు లేవు, ఇబ్బంది లేదు",
  "abt.pillar3.d": "ఒక సర్వర్-సైడ్ రిలేయర్ మీ కోసం ఆన్-చెయిన్ చర్యలపై సంతకం చేస్తుంది. పౌరులు ఫోన్ నంబర్‌తో నమోదు చేసుకుంటారు — పోగొట్టుకోవడానికి వాలెట్‌లు లేదా సీడ్ ఫ్రేజ్‌లు ఏవీ లేవు.",
  "abt.pillar4.t": "ఖర్చు, మళ్లింపు కాదు",
  "abt.pillar4.d": "ప్రయోజనాలు డిజిటల్ రూపాయి, ఇవి ఆమోదిత, వర్గ-సరిపోలిన విక్రేతల వద్ద మాత్రమే ఖర్చు చేయదగినవి — నగదు బదిలీలను పీడించే లీకేజీని మూసివేస్తుంది.",
