  "home.spot.feature.title": "ପ୍ରତ୍ୟେକ ବିତରଣ, ସାର୍ବଜନୀନ ଭାବେ ଯାଞ୍ଚଯୋଗ୍ୟ",
  "home.spot.feature.body": "ଯେକେହି ଗୋଟିଏ ସୁବିଧାକୁ ମଞ୍ଜୁରୀଠାରୁ ଖର୍ଚ୍ଚ ପର୍ଯ୍ୟନ୍ତ ଖୋଜିପାରିବେ — ହିତାଧିକାରୀଙ୍କ ପରିଚୟ ପ୍ରକାଶ ନକରି। ZK ପ୍ରୁଫ ତଥ୍ୟ ଗୋପନୀୟ ରଖେ ଓ ସିଷ୍ଟମକୁ ସତ୍ୟନିଷ୍ଠ ରଖେ।",
