  "sch.sub": "କ୍ଷେତ୍ର ଅନୁଯାୟୀ ସକ୍ରିୟ ଯୋଜନା ଦେଖନ୍ତୁ। ଯୋଗ୍ୟତା ବ୍ୟକ୍ତିଗତ ଭାବେ ଯାଞ୍ଚ କରି ଆବେଦନ କରିବାକୁ ଗୋଟିଏ ବାଛନ୍ତୁ — ସୁବିଧା ଡିଜିଟାଲ ଟଙ୍କା ଭାବେ ଆସେ, କେବଳ ଅନୁମୋଦିତ ବିକ୍ରେତାଙ୍କ ପାଖରେ ଖର୍ଚ୍ଚଯୋଗ୍ୟ।",
