  "sch.upSub": "ଅଧିକ ନାଗରିକ-ରୁ-ବିକ୍ରେତା କାର୍ଯ୍ୟକ୍ରମ ଅନ୍-ଚେନ୍ ଯୋଡ଼ିବା ପାଇଁ ପ୍ରସ୍ତୁତ ହେଉଛି — ଚାଲୁଥିବା ଯୋଜନା ପରି, ସୁବିଧା କେବଳ ସେମାନଙ୍କ ଅନୁମୋଦିତ ବିକ୍ରେତାଙ୍କ ପାଖରେ ଖର୍ଚ୍ଚ କରାଯାଇପାରିବ।",
