  "sch.up.suryaghar": "ପରିବାରଙ୍କ ପାଇଁ ଛାତ-ସୌର ସବସିଡି, ପଞ୍ଜୀକୃତ ସୋଲାର ଇନଷ୍ଟଲରଙ୍କ ମାଧ୍ୟମରେ।",
  "sch.up.pmjay": "ତାଲିକାଭୁକ୍ତ ଡାକ୍ତରଖାନାରେ ପରିବାର ପିଛା ବର୍ଷକୁ ₹5 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ କ୍ୟାଶଲେସ୍ ଚିକିତ୍ସା।",
  "sch.up.pds": "ରାସନ-କାର୍ଡଧାରୀଙ୍କ ପାଇଁ ଲାଇସେନ୍ସପ୍ରାପ୍ତ ଉଚିତ ମୂଲ୍ୟ ଦୋକାନରେ ସବସିଡିଯୁକ୍ତ ଖାଦ୍ୟଶସ୍ୟ।",
