  "sd.allSchemes": "← ସମସ୍ତ ଯୋଜନା",
  "sd.loadFail": "ଏହି ଯୋଜନା ଲୋଡ୍ ହୋଇପାରିଲା ନାହିଁ: {err}",
  "sd.about": "ଏହି ଯୋଜନା ବିଷୟରେ",
  "sd.defaultDesc": "ଏହି କଲ୍ୟାଣ ଯୋଜନା ଯୋଗ୍ୟ ହିତାଧିକାରୀଙ୍କ ଇ-ରୁପୀ ୱାଲେଟକୁ ନିର୍ଦ୍ଧାରିତ କିସ୍ତିରେ ସିଧାସଳଖ ସୁବିଧା ବିତରଣ କରେ। ଯୋଗ୍ୟତା ଗୋଟିଏ ଜିରୋ-ନଲେଜ ପ୍ରୁଫ ବ୍ୟବହାର କରି ସରକାରୀ ରେଜିଷ୍ଟ୍ରି ବିରୁଦ୍ଧରେ ବ୍ୟକ୍ତିଗତ ଭାବେ ଯାଞ୍ଚ କରାଯାଏ, ଏବଂ ପ୍ରତ୍ୟେକ ବିତରଣ ସାର୍ବଜନୀନ ଲେଜରରେ ଲିପିବଦ୍ଧ ହୁଏ।",
  "sd.spendableAt": "ସୁବିଧା ଖର୍ଚ୍ଚଯୋଗ୍ୟ ସ୍ଥାନ",
  "sd.howTitle": "ଏହା କିପରି କାମ କରେ",
  "sd.step1.t": "ଯୋଗ୍ୟତା ବ୍ୟକ୍ତିଗତ ଭାବେ ଯାଞ୍ଚ କରନ୍ତୁ",
  "sd.step1.d": "ଆପଣଙ୍କ ବିବରଣୀ ସରକାରୀ ରେଜିଷ୍ଟ୍ରି ସହ ମିଳାଯାଏ ଏବଂ ଗୋଟିଏ ଜିରୋ-ନଲେଜ ପ୍ରୁଫ ଦ୍ୱାରା ପ୍ରମାଣିତ ହୁଏ — କୌଣସି ସମ୍ବେଦନଶୀଳ ତଥ୍ୟ ଅସୁରକ୍ଷିତ ଭାବେ ଆପଣଙ୍କ ଡିଭାଇସ ଛାଡେ ନାହିଁ।",
  "sd.step2.t": "ଅନ-ଚେନ ନାମାଙ୍କନ କରନ୍ତୁ",
  "sd.step2.d": "ପ୍ରୁଫ ଯାଞ୍ଚ ହେବା ମାତ୍ରେ, ଆପଣ ରିଲେୟର ମାଧ୍ୟମରେ ସାର୍ବଜନୀନ ଲେଜରରେ ଯୋଜନାରେ ନାମାଙ୍କିତ ହୁଅନ୍ତି — ପରିଚାଳନା କରିବାକୁ କୌଣସି ବ୍ୟକ୍ତିଗତ କୀ ନାହିଁ।",
