  "sd.step3.d": "ପ୍ରତ୍ୟେକ କିସ୍ତି ସମୟସୂଚୀ ଅନୁଯାୟୀ ସିଧାସଳଖ ଆପଣଙ୍କ ଇ-ରୁପୀ ୱାଲେଟକୁ ବିତରିତ ହୁଏ।",
  "sd.step4.t": "ଅନୁମୋଦିତ ବିକ୍ରେତାଙ୍କ ପାଖରେ ଖର୍ଚ୍ଚ କରନ୍ତୁ",
