  "abt.sub": "BharatChain ସରକାରୀ ସୁବିଧାକୁ ଏକ ସାର୍ବଜନୀନ ଲେଜରରେ ଡିଜିଟାଲ ଟଙ୍କା ଭାବେ ବିତରଣ କରେ — ପ୍ରତ୍ୟେକ ହିତାଧିକାରୀଙ୍କ ବ୍ୟକ୍ତିଗତ ତଥ୍ୟକୁ ଜିରୋ-ନଲେଜ ପ୍ରୁଫ ଦ୍ୱାରା ଗୋପନୀୟ ରଖି ଅପଚୟ ଦୂର କରେ।",
