  "abt.pillar1.d": "ଯୋଗ୍ୟତା ସରକାରୀ ରେଜିଷ୍ଟ୍ରି ବିରୁଦ୍ଧରେ ଗୋଟିଏ ଜିରୋ-ନଲେଜ ପ୍ରୁଫ ଦ୍ୱାରା ପ୍ରମାଣିତ ହୁଏ। ସିଷ୍ଟମ ଜାଣେ ଯେ ଆପଣ ଯୋଗ୍ୟ — କେବେ ଆପଣଙ୍କ ଅନ୍ତର୍ନିହିତ ବ୍ୟକ୍ତିଗତ ତଥ୍ୟ ନୁହେଁ।",
