  "sch.up.ujjwala": "അർഹരായ കുടുംബങ്ങൾക്ക് അംഗീകൃത ഗ്യാസ് വിതരണക്കാർ വഴി സബ്സിഡിയുള്ള LPG സിലിണ്ടറുകൾ.",
  "sd.allSchemes": "← എല്ലാ പദ്ധതികളും",
  "sd.loadFail": "ഈ പദ്ധതി ലോഡ് ചെയ്യാനായില്ല: {err}",
  "sd.about": "ഈ പദ്ധതിയെക്കുറിച്ച്",
  "sd.defaultDesc": "ഈ ക്ഷേമ പദ്ധതി യോഗ്യരായ ഗുണഭോക്താക്കളുടെ ഇ-റുപ്പീ വാലറ്റുകളിലേക്ക് ഷെഡ്യൂൾ ചെയ്ത ഗഡുക്കളായി ആനുകൂല്യങ്ങൾ നേരിട്ട് വിതരണം ചെയ്യുന്നു. യോഗ്യത ഒരു സീറോ-നോളജ് പ്രൂഫ് ഉപയോഗിച്ച് സർക്കാർ രജിസ്ട്രിക്കെതിരെ സ്വകാര്യമായി പരിശോധിക്കുന്നു, ഓരോ വിതരണവും പൊതു ലെഡ്ജറിൽ രേഖപ്പെടുത്തുന്നു.",
  "sd.spendableAt": "ആനുകൂല്യം ചെലവഴിക്കാവുന്നത്",
  "sd.howTitle": "ഇത് എങ്ങനെ പ്രവർത്തിക്കുന്നു",
  "sd.step1.t": "യോഗ്യത സ്വകാര്യമായി പരിശോധിക്കുക",
  "sd.step1.d": "നിങ്ങളുടെ വിശദാംശങ്ങൾ സർക്കാർ രജിസ്ട്രിയുമായി പൊരുത്തപ്പെടുത്തി ഒരു സീറോ-നോളജ് പ്രൂഫ് ഉപയോഗിച്ച് തെളിയിക്കുന്നു — സെൻസിറ്റീവ് ഡാറ്റയൊന്നും സംരക്ഷണമില്ലാതെ നിങ്ങളുടെ ഉപകരണം വിടുന്നില്ല.",
  "sd.step2.t": "ഓൺ-ചെയിനിൽ എൻറോൾ ചെയ്യുക",
  "sd.step2.d": "തെളിവ് പരിശോധിച്ചാൽ, റിലേയർ വഴി പൊതു ലെഡ്ജറിൽ പദ്ധതിയിലേക്ക് നിങ്ങൾ എൻറോൾ ചെയ്യപ്പെടുന്നു — കൈകാര്യം ചെയ്യാൻ സ്വകാര്യ കീകളൊന്നുമില്ല.",
  "sd.step3.t": "ഡിജിറ്റൽ രൂപ സ്വീകരിക്കുക",
  "sd.step3.d": "ഓരോ ഗഡുവും ഷെഡ്യൂൾ പ്രകാരം നിങ്ങളുടെ ഇ-റുപ്പീ വാലറ്റിലേക്ക് നേരിട്ട് വിതരണം ചെയ്യുന്നു.",
  "sd.step4.t": "അംഗീകൃത വിൽപ്പനക്കാരിൽ ചെലവഴിക്കുക",
  "sd.step4.d": "നിങ്ങളുടെ വാലറ്റിൽ നിന്ന് അംഗീകൃത വിൽപ്പനക്കാർക്ക് നേരിട്ട് പണം നൽകുക; ഓരോ രൂപയും തുടക്കം മുതൽ ഒടുക്കം വരെ ഓഡിറ്റ് ചെയ്യാവുന്നതായി തുടരുന്നു.",
  "sd.perInstallment": "ഓരോ ഗഡുവിനും",
  "sd.outlay": "ആകെ പദ്ധതി വിഹിതം",
  "sd.disbursedSoFar": "ഇതുവരെ വിതരണം ചെയ്തു",
  "sd.remaining": "ബാക്കിയുള്ളത്",
  "sd.applyCta": "യോഗ്യത പരിശോധിക്കുക & അപേക്ഷിക്കുക",
  "sd.signInApply": "അപേക്ഷിക്കാൻ സൈൻ ഇൻ ചെയ്യുക",
  "sd.zkHint": "യോഗ്യത ഒരു ZK പ്രൂഫ് ഉപയോഗിച്ച് സ്വകാര്യമായി തെളിയിക്കുന്നു.",
  "led.live": "തത്സമയം",
  "led.title": "ഓരോ രൂപയും എവിടെ പോകുന്നു",
  "led.sub": "ക്ഷേമ പണത്തിന്റെ ഒഴുക്കിന്റെ ഒരു തത്സമയ, പൊതു കാഴ്ച — അനുവദിച്ചത്, വിതരണം ചെയ്തത്, ചെലവഴിച്ചത്. ഗുണഭോക്താക്കളുടെ വ്യക്തിത്വം സീറോ-നോളജ് പ്രൂഫുകൾ വഴി സ്വകാര്യമായി തുടരുന്നു; പണത്തിന്റെ പാത പൂർണ്ണമായും ഓഡിറ്റ് ചെയ്യാവുന്നതായി തുടരുന്നു.",
  "led.loadFail": "ലെഡ്ജർ ലോഡ് ചെയ്യാനായില്ല: {err}. ബാക്കെൻഡ് :3001-ൽ പ്രവർത്തിക്കുന്നുണ്ടോ?",
  "led.mDisbursed": "സുതാര്യമായി വിതരണം ചെയ്തു",
  "led.mOutlay": "ആകെ അനുവദിച്ച വിഹിതം",
  "led.mLeakage": "ചോർച്ച — ഓൺ-ചെയിനിൽ ഓഡിറ്റ് ചെയ്തു",
  "led.overall": "മൊത്തം വിതരണം",
