  "led.byScheme": "പദ്ധതി തിരിച്ച്",
  "led.th.scheme": "പദ്ധതി",
  "led.th.sector": "മേഖല",
  "led.th.installment": "ഗഡു",
  "led.th.disbursed": "വിതരണം ചെയ്തു",
  "led.th.outlay": "വിഹിതം",
  "led.th.progress": "പുരോഗതി",
  "led.flowTitle": "പണത്തിന്റെ ഒഴുക്ക്",
  "led.flowSub": "ഓരോ ആനുകൂല്യവും ഒരേ ഓഡിറ്റ് ചെയ്യാവുന്ന പാതയിലൂടെ സഞ്ചരിക്കുന്നു.",
  "led.flow1.t": "RBI അനുവദിക്കുന്നു",
  "led.flow1.d": "റിസർവ് ബാങ്ക് പദ്ധതി ഫണ്ടുകൾ ഡിജിറ്റൽ രൂപയായി ഓൺ-ചെയിൻ ട്രഷറിയിലേക്ക് മിന്റ് ചെയ്യുന്നു.",
  "led.flow2.t": "പൗരൻ സ്വീകരിക്കുന്നു",
  "led.flow2.d": "യോഗ്യരായ, ZK-പരിശോധിച്ച ഗുണഭോക്താക്കൾക്ക് ഗഡുക്കൾ നേരിട്ട് അവരുടെ വാലറ്റിലേക്ക് വിതരണം ചെയ്യുന്നു.",
  "led.flow3.t": "വിൽപ്പനക്കാരന് പണം നൽകുന്നു",
  "led.flow3.d": "പൗരന്മാർ അംഗീകൃത വിൽപ്പനക്കാരിൽ ചെലവഴിക്കുന്നു; ഫണ്ടുകൾ പദ്ധതിക്ക് വിഭാഗ-പരിമിതമാണ്.",
  "led.flow4.t": "വിൽപ്പനക്കാരൻ റിഡീം ചെയ്യുന്നു",
  "led.flow4.d": "വിൽപ്പനക്കാർ ഇ-റുപ്പീ വീണ്ടും ഫിയറ്റ് പണമായി റിഡീം ചെയ്യുന്നു — RBI-അംഗീകൃതവും പൂർണ്ണമായി രേഖപ്പെടുത്തിയതും.",
  "led.portalNote": "സൈൻ ഇൻ ചെയ്ത പൗരന്മാരും ഉദ്യോഗസ്ഥരും അവരുടെ പോർട്ടലിനുള്ളിൽ സ്വന്തം പ്രവർത്തനത്തിന്റെ ഇടപാട്-തല വിശദാംശങ്ങൾ കാണുന്നു.",
  "abt.title": "നിങ്ങൾക്ക് പരിശോധിക്കാവുന്ന ക്ഷേമം, വിശ്വസിക്കാവുന്ന സ്വകാര്യത",
  "abt.sub": "BharatChain സർക്കാർ ആനുകൂല്യങ്ങൾ ഡിജിറ്റൽ രൂപയായി ഒരു പൊതു ലെഡ്ജറിൽ വിതരണം ചെയ്യുന്നു — ഓരോ ഗുണഭോക്താവിന്റെയും വ്യക്തിഗത ഡാറ്റ സീറോ-നോളജ് പ്രൂഫുകൾ ഉപയോഗിച്ച് സ്വകാര്യമായി സൂക്ഷിക്കുമ്പോൾ ചോർച്ച ഇല്ലാതാക്കുന്നു.",
  "abt.browse": "പദ്ധതികൾ കാണുക",
  "abt.seeLedger": "ലെഡ്ജർ കാണുക",
  "abt.principles": "നാല് തത്വങ്ങൾ",
  "abt.pillar1.t": "രൂപകൽപ്പന കൊണ്ട് സ്വകാര്യം",
  "abt.pillar1.d": "യോഗ്യത സർക്കാർ രജിസ്ട്രിക്കെതിരെ ഒരു സീറോ-നോളജ് പ്രൂഫ് ഉപയോഗിച്ച് തെളിയിക്കുന്നു. നിങ്ങൾ യോഗ്യനാണെന്ന് സിസ്റ്റം മനസ്സിലാക്കുന്നു — നിങ്ങളുടെ അടിസ്ഥാന വ്യക്തിഗത ഡാറ്റ ഒരിക്കലുമല്ല.",
  "abt.pillar2.t": "എല്ലാവർക്കും ഓഡിറ്റ് ചെയ്യാവുന്നത്",
  "abt.pillar2.d": "അനുമതികൾ, വിതരണങ്ങൾ, ചെലവുകൾ ഒരു പൊതു ലെഡ്ജറിൽ രേഖപ്പെടുത്തുന്നു. പണം ശരിയായ ആളുകളിലെത്തിയെന്ന് ആർക്കും പരിശോധിക്കാം — ഒരു വ്യക്തിത്വവും വെളിപ്പെടുത്താതെ.",
  "abt.pillar3.t": "കീകളില്ല, തടസ്സങ്ങളില്ല",
  "abt.pillar3.d": "ഒരു സെർവർ-സൈഡ് റിലേയർ നിങ്ങൾക്കായി ഓൺ-ചെയിൻ പ്രവർത്തനങ്ങൾ ഒപ്പിടുന്നു. പൗരന്മാർ ഒരു ഫോൺ നമ്പർ ഉപയോഗിച്ച് സൈൻ അപ്പ് ചെയ്യുന്നു — നഷ്ടപ്പെടാൻ വാലറ്റുകളോ സീഡ് ഫ്രെയ്സുകളോ ഇല്ല.",
  "abt.pillar4.t": "ചെലവഴിക്കുക, വഴിതിരിച്ചുവിടരുത്",
  "abt.pillar4.d": "ആനുകൂല്യങ്ങൾ അംഗീകൃതവും വിഭാഗം-പൊരുത്തപ്പെട്ടതുമായ വിൽപ്പനക്കാരിൽ മാത്രം ചെലവഴിക്കാവുന്ന ഡിജിറ്റൽ രൂപയാണ് — പണ കൈമാറ്റങ്ങളെ ബാധിക്കുന്ന ചോർച്ച അടച്ചുകൊണ്ട്.",
  "abt.lifecycle": "അനുമതി മുതൽ ചെലവ് വരെ",
  "abt.lifecycleSub": "BharatChain-ലെ ഒരു ആനുകൂല്യത്തിന്റെ പൂർണ്ണ ജീവിതചക്രം.",
  "abt.step1.t": "സർക്കാർ റഫറൻസ് രജിസ്ട്രി",
  "abt.step1.d": "ഗുണഭോക്തൃ, ബിസിനസ് യോഗ്യതാ ഡാറ്റ ഒരു മെർക്കിൾ കമ്മിറ്റ്മെന്റായി ഓൺ-ചെയിനിൽ ആങ്കർ ചെയ്യുന്നു — തെളിവുകൾക്കുള്ള സ്വകാര്യ സത്യ സ്രോതസ്സ്.",
  "abt.step2.t": "സീറോ-നോളജ് യോഗ്യത",
  "abt.step2.d": "ഒരു പൗരൻ (അല്ലെങ്കിൽ വിൽപ്പനക്കാരൻ) ഒരു പദ്ധതിയുടെ വ്യവസ്ഥ — വരുമാനം, വിഭാഗം, ഉടമസ്ഥത — തൃപ്തിപ്പെടുത്തുന്നുവെന്ന ഒരു തെളിവ് മൂല്യങ്ങൾ വെളിപ്പെടുത്താതെ സൃഷ്ടിക്കുന്നു.",
  "abt.step3.t": "റിലേയർ എൻറോൾമെന്റ്",
  "abt.step3.d": "പരിശോധിച്ച തെളിവ് ഓൺ-ചെയിനിൽ റിലേ ചെയ്യുന്നു, ഗുണഭോക്താവ് ആ പ്രത്യേക പദ്ധതിയുടെ ലെഡ്ജറിലേക്ക് എൻറോൾ ചെയ്യപ്പെടുന്നു.",
