  "sd.defaultDesc": "ਇਹ ਭਲਾਈ ਯੋਜਨਾ ਯੋਗ ਲਾਭਪਾਤਰੀਆਂ ਦੇ ਈ-ਰੁਪਇਆ ਵਾਲਿਟ ਵਿੱਚ ਨਿਯਤ ਕਿਸ਼ਤਾਂ ਰਾਹੀਂ ਲਾਭ ਸਿੱਧੇ ਵੰਡਦੀ ਹੈ। ਯੋਗਤਾ ਸਰਕਾਰੀ ਰਜਿਸਟਰੀ ਦੇ ਵਿਰੁੱਧ ਜ਼ੀਰੋ-ਨਾਲੇਜ ਪ੍ਰੂਫ਼ ਨਾਲ ਨਿੱਜੀ ਤੌਰ 'ਤੇ ਤਸਦੀਕ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਹਰ ਵੰਡ ਜਨਤਕ ਲੈਜ਼ਰ 'ਤੇ ਦਰਜ ਹੁੰਦੀ ਹੈ।",
