  "abt.pillar2.d": "ਮਨਜ਼ੂਰੀਆਂ, ਵੰਡਾਂ ਅਤੇ ਖਰਚੇ ਜਨਤਕ ਲੈਜ਼ਰ 'ਤੇ ਦਰਜ ਹੁੰਦੇ ਹਨ। ਕੋਈ ਵੀ ਪੁਸ਼ਟੀ ਕਰ ਸਕਦਾ ਹੈ ਕਿ ਪੈਸਾ ਸਹੀ ਲੋਕਾਂ ਤੱਕ ਪਹੁੰਚਿਆ — ਬਿਨਾਂ ਕਿਸੇ ਪਛਾਣ ਜ਼ਾਹਰ ਕੀਤੇ।",
  "abt.pillar3.t": "ਕੋਈ ਕੁੰਜੀਆਂ ਨਹੀਂ, ਕੋਈ ਰੁਕਾਵਟ ਨਹੀਂ",
  "abt.pillar3.d": "ਇੱਕ ਸਰਵਰ-ਸਾਈਡ ਰਿਲੇਅਰ ਤੁਹਾਡੇ ਲਈ ਆਨ-ਚੇਨ ਕਾਰਵਾਈਆਂ 'ਤੇ ਦਸਤਖਤ ਕਰਦਾ ਹੈ। ਨਾਗਰਿਕ ਇੱਕ ਫ਼ੋਨ ਨੰਬਰ ਨਾਲ ਸਾਈਨ ਅੱਪ ਕਰਦੇ ਹਨ — ਗੁਆਉਣ ਲਈ ਕੋਈ ਵਾਲਿਟ ਜਾਂ ਸੀਡ ਫ੍ਰੇਜ਼ ਨਹੀਂ।",
