  "abt.lifecycle": "ਮਨਜ਼ੂਰੀ ਤੋਂ ਖਰਚ ਤੱਕ",
  "abt.lifecycleSub": "BharatChain 'ਤੇ ਕਿਸੇ ਲਾਭ ਦਾ ਪੂਰਾ ਜੀਵਨ-ਚੱਕਰ।",
