  "abt.pillar1.d": "চৰকাৰী ৰেজিষ্ট্ৰীৰ বিপৰীতে এটা জিৰো-নলেজ প্ৰুফেৰে যোগ্যতা প্ৰমাণিত হয়। ছিষ্টেমে জানে যে আপুনি যোগ্য — কেতিয়াও আপোনাৰ অন্তৰ্নিহিত ব্যক্তিগত তথ্য নহয়।",
