  "abt.pillar2.d": "মঞ্জুৰি, বিতৰণ আৰু খৰচ এটা ৰাজহুৱা লেজাৰত ৰেকৰ্ড কৰা হয়। যিকোনো ব্যক্তিয়ে সত্যাপন কৰিব পাৰে যে ধন সঠিক লোকৰ ওচৰ পালেহি — কোনো পৰিচয় প্ৰকাশ নকৰাকৈ।",
  "abt.pillar3.t": "কোনো কী নাই, কোনো অসুবিধা নাই",
  "abt.pillar3.d": "এটা ছাৰ্ভাৰ-ছাইড ৰিলেৰে আপোনাৰ হৈ অন-চেইন কাৰ্য চহী কৰে। নাগৰিকে এটা ফোন নম্বৰেৰে চাইন আপ কৰে — হেৰুৱাবলগীয়া কোনো ৱালেট বা ছিড ফ্ৰেজ নাই।",
  "abt.pillar4.t": "খৰচ, অপব্যৱহাৰ নহয়",
  "abt.pillar4.d": "সুবিধা হৈছে ডিজিটেল টকা যিটো কেৱল অনুমোদিত, শ্ৰেণী-মিল খোৱা বিক্ৰেতাৰ ওচৰত খৰচ কৰিব পাৰি — নগদ স্থানান্তৰক বাধাগ্ৰস্ত কৰা লিকেজ বন্ধ কৰি।",
  "abt.lifecycle": "মঞ্জুৰিৰ পৰা খৰচলৈ",
  "abt.lifecycleSub": "BharatChain-ত এটা সুবিধাৰ সম্পূৰ্ণ জীৱনচক্ৰ।",
  "abt.step1.t": "চৰকাৰী ৰেফাৰেন্স ৰেজিষ্ট্ৰী",
  "abt.step1.d": "হিতাধিকাৰী আৰু ব্যৱসায়ৰ যোগ্যতা তথ্য এটা মাৰ্কেল কমিটমেণ্ট হিচাপে অন-চেইন এংকৰ কৰা হয় — প্ৰমাণৰ বাবে সত্যৰ গোপন উৎস।",
