  "abt.step2.d": "এজন নাগৰিকে (বা বিক্ৰেতাই) এটা প্ৰমাণ সৃষ্টি কৰে যে তেওঁ এটা আঁচনিৰ চৰ্ত পূৰণ কৰে — আয়, শ্ৰেণী, মালিকীস্বত্ব — মানবোৰ প্ৰকাশ নকৰাকৈ।",
  "abt.step3.t": "ৰিলেৰ নামভৰ্তি",
  "abt.step3.d": "সত্যাপিত প্ৰমাণ অন-চেইন ৰিলে কৰা হয় আৰু হিতাধিকাৰীক সেই নিৰ্দিষ্ট আঁচনিৰ লেজাৰত নামভৰ্তি কৰা হয়।",
  "abt.step4.t": "নিৰ্ধাৰিত বিতৰণ",
  "abt.step4.d": "প্ৰতিটো কিস্তি ই-ৰুপী হিচাপে সৃষ্টি কৰি নামভৰ্তি ৱালেটলৈ বিতৰণ কৰা হয়, দেৰিকৈ নামভৰ্তি হোৱাসকলক সামৰি আৰু মুঠ পৰিমাণ সীমাবদ্ধ কৰি।",
  "abt.step5.t": "অনুমোদিত বিক্ৰেতাৰ ওচৰত খৰচ কৰক",
  "abt.step5.d": "নাগৰিকে পোনপটীয়াকৈ বিক্ৰেতাক পৰিশোধ কৰে; পৰিশোধ শ্ৰেণী-সীমিত যাতে পুঁজি অপব্যৱহাৰ কৰিব নোৱাৰি।",
  "abt.step6.t": "বিক্ৰেতা মোচন",
  "abt.step6.d": "বিক্ৰেতাই সংগৃহীত ই-ৰুপী RBI অনুমোদনৰ সৈতে নগদলৈ মোচন কৰে — ৰাজহুৱা লেজাৰত প্ৰতিটো খোজ।",
  "abt.participants": "প্ৰতিজন অংশগ্ৰহণকাৰীৰ বাবে নিৰ্মিত",
